PAGE = 'নিজস্ব অনুশীলনী; বোর্ড-প্রশ্ন নয়; মূল বইয়ের পৃষ্ঠা যাচাই বাকি'
items, review = [], []

def fmt(x):
    x = F(x)
    d = Decimal(x.numerator) / Decimal(x.denominator)
    s = format(d.quantize(Decimal('0.000001'), rounding=ROUND_HALF_UP), 'f').rstrip('0').rstrip('.')
    return s if s and s != '-0' else '0'

def add(kind, text, explanation, family, **kw):
    row = dict(type=kind, text=text, explanation=explanation, page=PAGE, difficulty=kw.pop('difficulty', 'MEDIUM'), **kw)
    items.append(row)
    review.append(dict(index=len(items), kind=kind, family=family, originalPractice=True,
                       teacherApproved=False, sourcePageVerified=False))

def mcq(q, good, wrong, why, family, evidence=None):
    assert len(wrong) == 3
    opts = [str(good), *map(str, wrong)]
    assert len(set(opts)) == 4, (q, opts)
    pos = len([r for r in review if r['kind'] == 'MCQ']) % 4
    opts.insert(pos, opts.pop(0))
    add('MCQ', q, why, family, options=dict(zip('ABCD', opts)), correct='ABCD'[pos])
    if evidence:
        review[-1]['calculation'] = evidence

def numeric(q, val, unit, why, family, evidence):
    v = F(val)
    candidates = [v * 10, v / 10, v * 100, v + 1, v * 2, v * 3, v + 2]
    wrong = []
    good = fmt(v) + unit
    for x in candidates:
        s = fmt(x) + unit
        if s != good and s not in wrong:
            wrong.append(s)
        if len(wrong) == 3:
            break
    mcq(q, good, wrong, why, family, evidence)

